# ============================================================
# HTML RENDER HELPER
# IMPORTANT: dedent prevents Streamlit from treating HTML
# as a Markdown code block.
# ============================================================

def render_html(content):
    # Remove indentation from EVERY line. This prevents Streamlit
    # Markdown from interpreting indented HTML as a code block.
    cleaned = "\n".join(line.lstrip() for line in dedent(content).splitlines()).strip()
    st.markdown(cleaned, unsafe_allow_html=True)


# ============================================================
# LOGO HELPER (uses the embedded LOGO_BASE64 constant above —
# no separate image file needed)
# ============================================================

def get_logo_base64():
    return LOGO_BASE64


def render_logo(max_width="100%", margin="0 0 14px 0"):
    render_html(
        f"""
        <img src="data:image/png;base64,{LOGO_BASE64}"
             style="max-width:{max_width}; width:100%; height:auto;
                    display:block; margin:{margin};" />
        """
    )


