def image_src(asset_key):
    """Return a local base64 image when available, otherwise a verified remote fallback."""
    asset = IMAGE_ASSETS[asset_key]
    local_path = IMAGE_ASSET_DIR / asset["file"]
    if local_path.exists():
        try:
            data = base64.b64encode(local_path.read_bytes()).decode("ascii")
            return f"data:image/webp;base64,{data}"
        except Exception:
            pass
    return asset["url"]

def image_alt(asset_key):
    return IMAGE_ASSETS[asset_key]["alt"]

def image_credit(asset_key):
    asset = IMAGE_ASSETS[asset_key]
    return (
        f'<div class="image-credit">Image: {escape(asset["photographer"])} · '
        f'<a href="{asset["page"]}" target="_blank" rel="noopener noreferrer">source / license</a>'
        '</div>'
    )

def _download_missing_image_assets():
    """Best-effort first-run download of the verified Unsplash assets.

    If internet access is unavailable, the app simply keeps the verified
    remote fallback URL and continues running. Downloaded files are resized
    and converted to WebP for faster local loading.
    """
    marker = IMAGE_ASSET_DIR / ".download_checked"
    if marker.exists():
        return
    for asset in IMAGE_ASSETS.values():
        target = IMAGE_ASSET_DIR / asset["file"]
        if target.exists():
            continue
        try:
            req = Request(asset["url"], headers={"User-Agent": "OilSafe-Intelligence/1.0"})
            with urlopen(req, timeout=12) as response:
                raw = response.read()
            img = Image.open(io.BytesIO(raw)).convert("RGB")
            img.thumbnail((1800, 1200), Image.Resampling.LANCZOS)
            img.save(target, "WEBP", quality=78, method=6)
        except Exception:
            # Keep the verified remote fallback. Never break the safety app
            # because an optional decorative image cannot be downloaded.
            continue
    try:
        marker.write_text(datetime.now().isoformat(), encoding="utf-8")
    except Exception:
        pass

# Do not download decorative assets during every Streamlit process start.
# Remote URLs remain the fallback, while locally bundled WebP files are used when present.
AUTH_BG_IMAGE = image_src("refinery")


def _load_users():
    if USERS_FILE.exists():
        try:
            return _json.loads(USERS_FILE.read_text())
        except Exception:
            return {}
    return {}


def _save_users(users):
    try:
        USERS_FILE.write_text(_json.dumps(users, indent=2))
        return True
    except Exception:
        # Read-only filesystem / no backend attached yet — prototype
        # falls back to session-only accounts so the demo still works.
        return False


def _hash_password(password, salt=None):
    salt = salt or secrets.token_hex(16)
    digest = hashlib.sha256((salt + password).encode("utf-8")).hexdigest()
    return salt, digest


def _verify_password(password, salt, digest):
    return hashlib.sha256((salt + password).encode("utf-8")).hexdigest() == digest


def _create_account(full_name, email, username, password):
    users = _load_users()
    users.update(st.session_state.get("_session_users", {}))

    if not full_name or not email or not username or not password:
        return False, "Please fill in every field."
    if "@" not in email or "." not in email.split("@")[-1]:
        return False, "Please enter a valid email address."
    if username in users:
        return False, "That username is already taken."
    if any(u.get("email", "").lower() == email.lower() for u in users.values()):
        return False, "An account with that email already exists."
    if len(password) < 6:
        return False, "Password should be at least 6 characters."

    salt, digest = _hash_password(password)
    record = {"full_name": full_name, "email": email, "salt": salt, "hash": digest}

    users[username] = record
    persisted = _save_users(users)
    if not persisted:
        # Keep the new account available for the rest of this session.
        session_users = st.session_state.get("_session_users", {})
        session_users[username] = record
        st.session_state._session_users = session_users

    return True, "Account created. Please sign in."


def _authenticate(identifier, password):
    users = _load_users()
    users.update(st.session_state.get("_session_users", {}))

    match_username = identifier if identifier in users else None
    if match_username is None:
        for uname, u in users.items():
            if u.get("email", "").lower() == identifier.lower():
                match_username = uname
                break

    user = users.get(match_username) if match_username else None
    if not user:
        return False, None

    if _verify_password(password, user["salt"], user["hash"]):
        return True, {
            "username": match_username,
            "full_name": user.get("full_name", match_username),
        }
    return False, None


