def _severity_signals(text):
    """Detect explicit consequence/severity language from the report.

    This is a safety escalation layer, not a replacement for the ML model.
    Explicit fatality/serious-injury language must not be diluted by a
    statistical classifier trained on representative observations.
    """
    lower = text.lower()
    critical_terms = [
        "fatal", "fatality", "died", "death", "succumbed",
        "succumbed to", "killed", "life threatening", "life-threatening",
    ]
    serious_terms = [
        "serious injury", "serious injuries", "severe injury",
        "hospitalized", "hospitalised", "lost time injury", "major injury",
    ]
    critical_hits = [term for term in critical_terms if term in lower]
    serious_hits = [term for term in serious_terms if term in lower]
    return critical_hits, serious_hits


def _risk_fusion(text, ml_risk, precursor, ml_confidence):
    """Fuse ML risk with explicit consequence and high-energy hazard signals."""
    critical_hits, serious_hits = _severity_signals(text)
    lower = text.lower()

    high_energy_terms = [
        "break out tong", "break-out tong", "line of fire", "struck by",
        "hit by", "hydrocarbon release", "gas release", "confined space",
        "electrical contact", "fall from height", "suspended load",
        "fire and explosion", "explosion",
    ]
    energy_hits = [term for term in high_energy_terms if term in lower]

    # Explicit fatality/death or serious injury always escalates to HIGH.
    # The application has HIGH as its maximum operational risk label.
    if critical_hits or serious_hits:
        final_risk = "HIGH"
    elif ml_risk == "HIGH" or (precursor in {
        "Struck By / Line of Fire", "Fall from Height",
        "Process Safety Barrier Failure", "Fire and Explosion Potential",
        "Loss of Containment", "Confined Space Exposure",
        "Electrical Contact", "Vehicle-Pedestrian Interaction",
        "Dropped Object", "Excavation / Ground Hazard",
        "Permit Control Failure",
    } and energy_hits):
        final_risk = "HIGH"
    else:
        final_risk = ml_risk

    # Confidence is reported as confidence in the final assessment, not as
    # a claim that the model itself is certain. Explicit severity evidence
    # provides a strong deterministic signal.
    if critical_hits:
        fused_confidence = max(float(ml_confidence), 0.95)
    elif serious_hits:
        fused_confidence = max(float(ml_confidence), 0.90)
    elif final_risk == "HIGH":
        fused_confidence = max(float(ml_confidence), 0.75)
    else:
        fused_confidence = float(ml_confidence)

    return final_risk, min(fused_confidence, 0.99), critical_hits, serious_hits, energy_hits


def analyze_report(text):
    if not text or not text.strip():
        return None

    clean_text = text.strip()

    ml_risk = risk_model.predict([clean_text])[0]
    precursor = precursor_model.predict([clean_text])[0]
    ml_confidence = float(risk_model.predict_proba([clean_text]).max())

    risk, confidence, critical_hits, serious_hits, energy_hits = _risk_fusion(
        clean_text, ml_risk, precursor, ml_confidence
    )

    lower_text = clean_text.lower()

    evidence = [
        keyword
        for keyword in precursor_keywords.get(precursor, [])
        if keyword.lower() in lower_text
    ]

    # Add explicit consequence evidence so the explanation is auditable.
    evidence += critical_hits + serious_hits
    evidence = list(dict.fromkeys(evidence))

    if not evidence:
        evidence = ["Model-based NLP signal detected"]

    priority = "IMMEDIATE" if risk == "HIGH" else (
        "CORRECTIVE" if risk == "MEDIUM" else "ROUTINE"
    )

    # Fatal/serious-injury wording overrides priority as an explicit safety
    # escalation rule.
    if critical_hits or serious_hits:
        priority = "IMMEDIATE"

    barrier_analysis = analyze_safety_barriers(precursor, risk, evidence)

    # Replace generic fallback controls whenever a known precursor exists.
    actions = recommended_actions.get(
        precursor,
        ["Review observation and apply appropriate HSE controls."],
    )

    return {
        "risk": risk,
        "ml_risk": ml_risk,
        "precursor": precursor,
        "confidence": confidence,
        "ml_confidence": ml_confidence,
        "evidence": evidence,
        "severity_signals": critical_hits + serious_hits,
        "high_energy_signals": energy_hits,
        "barriers": barrier_analysis["barriers"],
        "barrier_status": barrier_analysis["overall"],
        "actions": actions,
        "priority": priority,
        "review_status": "Pending HSE Review",
    }



# Patch the existing analysis function with the V2 layers without removing the original logic.
_original_analyze_report = analyze_report

def _sif_pathway_override(text, base):
    """Resolve high-energy SIF pathways that a single-label ML classifier can miss.

    This layer deliberately separates the *hazard pathway* from the model's
    historical precursor label. It is deterministic and auditable: every
    override is backed by explicit phrases found in the observation.
    """
    low = text.lower()

    # Stored-pressure / line-of-fire pathway: breaking containment while
    # residual pressure remains is a high-energy SIF precursor even when the
    # historical single-label ML classifier chooses another category.
    pressure_hits = [term for term in [
        "pressurized", "pressurised", "residual pressure", "stored pressure",
        "pressure indicator", "pressure gauge", "still showing pressure",
    ] if term in low]
    break_hits = [term for term in [
        "loosening a flange", "loosened a flange", "loosening flange",
        "opened the flange", "breaking containment", "break containment",
        "loosen bolts", "loosened bolts", "removed bolts",
        "connection moved", "flange connection",
    ] if term in low]
    line_fire_hits = [term for term in [
        "line of fire", "directly in front", "in front of the flange",
        "positioned in front", "standing in front", "no exclusion zone",
        "exclusion zone",
    ] if term in low]
    isolation_gap_hits = [term for term in [
        "without confirming", "not confirmed", "not completely depressurized",
        "not fully depressurized", "without depressurization",
        "without confirming that", "isolation not confirmed",
        "not isolated", "without isolation",
    ] if term in low]

    if pressure_hits and break_hits and (line_fire_hits or isolation_gap_hits):
        evidence = list(dict.fromkeys(pressure_hits + break_hits + line_fire_hits + isolation_gap_hits))
        return {
            "precursor": "Stored Pressure / Line of Fire",
            "pathway": "Residual stored pressure → flange/containment opened → uncontrolled pressure release → line-of-fire exposure → potential serious injury/fatality",
            "evidence": evidence,
            "actions": [
                "STOP work and move personnel out of the line-of-fire immediately.",
                "Do not loosen/open the flange until the system is isolated, depressurized and verified safe.",
                "Verify pressure indication and positive isolation before breaking containment.",
                "Establish an exclusion zone and require competent supervision before restart.",
            ],
            "confidence": 0.94,
        }

    # Fall-from-height pathway: height + fall/loss-of-balance + inadequate
    # edge/fall protection is more safety-critical than a generic slip/trip label.
    height_hits = [term for term in [
        "above ground", "metres above", "meters above", "metre above",
        "meter above", "working at height", "work at height", "elevated",
        "platform", "scaffold", "ladder",
    ] if term in low]
    fall_hits = [term for term in [
        "fall from height", "fell from", "lost balance", "loss of balance",
        "falling", "fall hazard", "fall protection", "edge protection",
        "harness", "full body harness", "lifeline", "life line",
    ] if term in low]
    protection_gap_hits = [term for term in [
        "no effective protection", "no edge protection", "without guardrail",
        "without guard rails", "without fall protection", "inadequate fall protection",
        "unprotected edge", "no guardrail", "no guard rail",
        "harness not connected", "harness was not connected",
        "harness not attached", "harness was not attached",
        "harness disconnected", "harness was disconnected",
        "without connecting the harness", "without connecting harness",
        "without connecting the full body harness",
        "full body harness not connected", "full body harness was not connected",
        "full body harness not attached", "full body harness was not attached",
        "lifeline not connected", "lifeline was not connected",
        "lifeline not attached", "lifeline was not attached",
        "life line not connected", "life line was not connected",
        "not connected to the lifeline", "not attached to the lifeline",
        "not connected to a lifeline", "not attached to a lifeline",
        "without connecting to the lifeline", "without connecting to a lifeline",
        "without being connected to the lifeline",
        "without being attached to the lifeline",
    ] if term in low]

    if len(height_hits) >= 1 and (fall_hits or protection_gap_hits):
        evidence = list(dict.fromkeys(height_hits + fall_hits + protection_gap_hits))
        return {
            "precursor": "Fall from Height",
            "pathway": "Working at height → inadequate fall protection → fall exposure → potential serious injury/fatality",
            "evidence": evidence,
            "actions": [
                "STOP work at height until the access/platform is made safe.",
                "Provide effective guardrails/edge protection or an approved fall-protection system.",
                "Verify anchorage, harness/lifeline and access equipment before restart.",
                "Establish an exclusion zone below and secure tools/materials against dropped objects.",
                "Require supervisor/HSE verification before the activity resumes.",
            ],
            "confidence": 0.88,
        }

    # Hydrocarbon release + ignition source is an ignition/fire/explosion pathway.
    # An electrical tool in this context is treated as a potential ignition source,
    # not automatically as an electrical-contact event.
    hydro_hits = [term for term in [
        "hydrocarbon", "hydrocarbon vapour", "hydrocarbon vapor", "flammable vapour",
        "flammable vapor", "gas leak", "gas leakage", "vapour", "vapor",
        "loss of containment", "leak", "leakage", "release",
    ] if term in low]
    ignition_hits = [term for term in [
        "ignition source", "electrical tool", "electrical equipment", "portable electrical",
        "spark", "sparks", "hot work", "welding", "ignition",
    ] if term in low]
    isolation_hits = [term for term in [
        "without fully confirming isolation", "not fully isolated", "incomplete isolation",
        "isolation not confirmed", "isolation failure", "opened without isolation",
        "without isolation",
    ] if term in low]
    alarm_hits = [term for term in [
        "gas detection alarm", "gas detector alarm", "gas alarm", "alarm activated",
        "alarm",
    ] if term in low]
    continued_hits = [term for term in [
        "work continued", "continued working", "continued for", "activity continued",
    ] if term in low]

    if hydro_hits and ignition_hits and (isolation_hits or alarm_hits):
        evidence = list(dict.fromkeys(hydro_hits + ignition_hits + isolation_hits + alarm_hits + continued_hits))
        return {
            "precursor": "Fire and Explosion Potential",
            "pathway": "Incomplete isolation → hydrocarbon release → flammable vapour → ignition source → fire/explosion potential",
            "evidence": evidence,
            "actions": [
                "STOP work and eliminate ignition sources from the release area.",
                "Isolate, depressurize and make the hydrocarbon source safe under the applicable procedure.",
                "Verify atmospheric testing/gas detection and establish the required exclusion zone.",
                "Confirm permit-to-work, isolation/LOTO and emergency shutdown controls before restart.",
                "Escalate immediately to the responsible supervisor/HSE team if a flammable atmosphere or release persists.",
            ],
            "confidence": 0.90,
        }

    return None


def analyze_report(text):
    normalized = multilingual_normalize(text)
    base = _original_analyze_report(normalized)
    if not base:
        return base

    override = _sif_pathway_override(normalized, base)
    if override:
        original_precursor = base.get("precursor")
        base["precursor"] = override["precursor"]
        base["pathway"] = override["pathway"]
        base["evidence"] = list(dict.fromkeys(base.get("evidence", []) + override["evidence"]))
        base["actions"] = override["actions"]
        base["priority"] = "IMMEDIATE"
        # Keep the original classifier result visible for auditability while
        # using the pathway assessment as the operational precursor.
        base["ml_precursor"] = original_precursor
        base["pathway_override"] = True
        base["pathway_confidence"] = override["confidence"]
    else:
        base["pathway"] = "ML precursor pathway; no high-energy rule override triggered"
        base["pathway_override"] = False
        base["pathway_confidence"] = None

    score, band, energy, consequences, latent, exposure, recurrence = compute_sif_score(base, normalized, df)
    consequence, consequence_conf, consequence_hits = predict_consequence(normalized)

    # Explicit high-energy pathways receive a consequence-aware score floor.
    # This is a screening score, not a calibrated probability.
    if override:
        if override["precursor"] == "Fire and Explosion Potential":
            score = max(score, 85)
            band = "CRITICAL"
            consequence = "Fire / Explosion"
            consequence_conf = max(consequence_conf, 0.88)
        elif override["precursor"] == "Fall from Height":
            score = max(score, 75)
            band = "HIGH"
            consequence = "Fall / Multiple Injury"
            consequence_conf = max(consequence_conf, 0.84)
        elif override["precursor"] == "Stored Pressure / Line of Fire":
            score = max(score, 82)
            band = "CRITICAL"
            consequence = "Major Release"
            consequence_conf = max(consequence_conf, 0.86)

        base["confidence"] = override["confidence"]

    # If the rule layer changes the precursor, rebuild the barriers for that
    # specific SIF pathway instead of retaining the original generic barrier set.
    if override:
        barrier_analysis = analyze_safety_barriers(base["precursor"], "HIGH", base["evidence"])
        base["barriers"] = barrier_analysis["barriers"]
        base["barrier_status"] = barrier_analysis["overall"]

    base.update({
        "normalized_text": normalized,
        "language": detect_language(text),
        "sif_score": score,
        "sif_band": band,
        "energy_sources": energy,
        "consequence": consequence,
        "consequence_confidence": consequence_conf,
        "consequence_hits": consequence_hits,
        "latent_conditions": latent,
        "exposure": exposure,
        "recurrence_count": recurrence,
        "knowledge_graph": build_knowledge_graph(base, normalized),
        "image_status": "Text assessment only",
    })
    return base


