# FINAL SAFETY-CONTEXT LAYER
# ============================================================
# The original prototype relied too heavily on keyword presence and ML labels.
# This layer is deliberately placed after the existing engine so it can correct
# false positives caused by negation, controls, barriers and lack of exposure.
# It does NOT replace the ML model; it adds an auditable context gate.

# Positive CONTROL evidence only. Absence-of-exposure phrases are kept
# separate so the UI never reports "Control confirmed: no worker".
_CONTEXT_POSITIVE = [
    "barricade intact", "barricading was intact", "barrier intact",
    "guard in place", "guard installed", "guard was installed",
    "fall protection provided", "fall protection was provided",
    "harness connected", "harness was connected", "lifeline connected",
    "permit verified", "permit was verified", "permit approved",
    "isolation confirmed", "isolation was confirmed", "fully isolated",
    "locked out", "lockout confirmed", "depressurized", "depressurised",
    "pressure was zero", "zero pressure", "gas test clear", "atmosphere clear",
    "work stopped", "activity stopped", "job stopped", "lifting stopped",
    "secured", "securely restrained", "area isolated", "area was isolated",
    "control was effective", "controls were effective", "controls were in place",
    "effective controls", "exclusion zone maintained", "exclusion zone was maintained",
    "safe distance maintained",
]

_NO_EXPOSURE = [
    "no personnel", "no person", "no worker", "no workers", "no employee",
    "no one was exposed", "no one entered", "no one entered the area",
    "outside the exclusion zone", "outside exclusion zone", "safe distance",
    "did not enter", "did not approach", "not exposed", "not in the line of fire",
    "kept clear", "kept outside", "maintained clear", "no active exposure",
]

_CONTEXT_FAILURE = [
    "without", "not provided", "not installed", "not in place", "not available",
    "missing", "removed", "failed", "failure", "damaged", "defective",
    "inadequate", "unprotected", "not verified", "not confirmed", "not isolated",
    "isolation not confirmed", "permit not verified", "permit missing",
    "no guardrail", "no guard rail", "no barricade", "no exclusion zone",
    "no fall protection", "no effective protection", "work continued",
]

_PEOPLE_WORDS = ["worker", "workers", "operator", "operators", "technician", "technicians", "employee", "employees", "person", "personnel", "contractor", "staff"]
_EXPOSURE_WORDS = [
    "near", "inside", "within", "under", "entered", "entering", "standing",
    "stood", "working", "positioned", "exposed", "exposure", "approached",
    "beneath", "underneath", "adjacent", "in the line of fire", "in impact zone",
]


def _sentence_list(text):
    import re
    return [s.strip() for s in re.split(r"(?<=[.!?;])\s+|\n+", text) if s.strip()]


def _sentence_has_any(sentence, terms):
    low = sentence.lower()
    return any(term in low for term in terms)


def _context_analysis(text):
    """Return explicit hazard/control/exposure context without treating words alone as proof."""
    import re
    sentences = _sentence_list(text)
    positive_hits = []
    failure_hits = []
    exposure_sentences = []
    no_exposure_sentences = []

    for s in sentences:
        low = s.lower()
        ph = [p for p in _CONTEXT_POSITIVE if p in low]
        fh = [f for f in _CONTEXT_FAILURE if f in low]
        positive_hits.extend(ph)
        failure_hits.extend(fh)

        people = _sentence_has_any(s, _PEOPLE_WORDS)
        exposure = _sentence_has_any(s, _EXPOSURE_WORDS)
        explicit_no_person = any(p in low for p in _NO_EXPOSURE)
        explicit_outside = any(p in low for p in [
            "outside the exclusion zone", "outside exclusion zone", "safe distance",
            "not in the line of fire", "kept clear", "kept outside",
        ])
        if people and exposure and not explicit_no_person and not explicit_outside:
            exposure_sentences.append(s)
        if explicit_no_person or explicit_outside or "no exposure" in low or "not exposed" in low:
            no_exposure_sentences.append(s)

    positive_hits = list(dict.fromkeys(positive_hits))
    failure_hits = list(dict.fromkeys(failure_hits))
    exposure_sentences = list(dict.fromkeys(exposure_sentences))
    no_exposure_sentences = list(dict.fromkeys(no_exposure_sentences))

    # A control is considered strong only when a positive control phrase is present
    # and there is no nearby explicit failure phrase for that same control concept.
    controlled = bool(positive_hits) and not bool(failure_hits)
    active_exposure = bool(exposure_sentences) and not bool(no_exposure_sentences)

    return {
        "positive_controls": positive_hits,
        "control_failures": failure_hits,
        "exposure_sentences": exposure_sentences,
        "no_exposure_sentences": no_exposure_sentences,
        "active_exposure": active_exposure,
        "controlled": controlled,
        "control_strength": "Effective" if controlled else ("Compromised" if failure_hits else "Not explicit"),
    }


def _precursor_context(text, precursor):
    """Determine whether the detected precursor is an active SIF pathway.

    Priority order is: explicit negative/absence -> explicit exposure/failure ->
    positive control. This prevents phrases such as "no personnel entered the
    line of fire" from being misread as an exposure merely because "entered"
    appears in the sentence.
    """
    import re
    low = text.lower()
    ctx = _context_analysis(text)

    def any_phrase(phrases):
        return any(p in low for p in phrases)

    def negated_phrase(phrases):
        # Common safety negation forms. Check the phrase itself rather than
        # relying on a generic keyword window.
        for p in phrases:
            if re.search(r"\b(?:no|not|never|did not|didn't|without)\s+(?:\w+\s+){0,4}" + re.escape(p) + r"\b", low):
                return True
        return False

    no_people = any_phrase([
        "no personnel", "no person", "no worker", "no workers", "no employee",
        "no one was exposed", "no one entered", "personnel were not exposed",
    ])

    if precursor == "Fall from Height":
        height = any_phrase(["working at height", "work at height", "above ground", "metres above", "meters above", "scaffold", "ladder", "elevated platform"])
        explicit_gap = any_phrase([
            "without fall protection", "no fall protection", "without guardrail", "without guard rail",
            "no guardrail", "no guard rail", "unprotected edge", "inadequate fall protection",
            "fall protection failed", "fall protection was missing", "guardrail missing",
            "harness not connected", "harness was not connected",
            "harness not attached", "harness was not attached",
            "harness disconnected", "harness was disconnected",
            "without connecting the harness", "without connecting harness",
            "without connecting the full body harness",
            "full body harness not connected", "full body harness was not connected",
            "full body harness not attached", "full body harness was not attached",
            "lifeline not connected", "lifeline was not connected",
            "lifeline not attached", "lifeline was not attached",
            "not connected to the lifeline", "not attached to the lifeline",
            "not connected to a lifeline", "not attached to a lifeline",
            "without connecting to the lifeline", "without connecting to a lifeline",
            "without being connected to the lifeline",
            "without being attached to the lifeline",
        ]) and not any_phrase([
            "fall protection provided", "guardrail installed", "guard rails installed",
            "edge protected", "harness connected", "harness was connected",
            "lifeline connected", "lifeline was connected",
        ])
        explicit_exposure = any_phrase([
            "worker was at height", "worker working at height", "worker was working at height",
            "worker was observed working at height", "worker observed working at height",
            "person was at height", "operator was at height", "worker was exposed to a fall",
            "worker was exposed to fall", "person was exposed to a fall",
        ]) and not no_people
        safe = any_phrase([
            "fall protection provided", "fall protection was provided", "harness connected",
            "harness was connected", "lifeline connected", "edge protected", "guardrail installed",
        ]) and not explicit_gap
        active = bool(height and (explicit_gap or explicit_exposure) and not safe)
        return {"active": active, "safe": bool(safe and not active), "reason": "Height exposure with a protection gap" if active else "Height hazard controlled or exposure not established"}

    if precursor in {"Struck By / Line of Fire", "Dropped Object", "Vehicle-Pedestrian Interaction"}:
        hazard = any_phrase([
            "line of fire", "struck by", "suspended load", "dropped object",
            "moving equipment", "moving vehicle", "impact zone", "vehicle movement",
        ])
        explicit_exposure = any_phrase([
            "worker entered the line of fire", "worker was in the line of fire",
            "worker was near the moving", "worker stood under", "worker stood beneath",
            "personnel were inside the exclusion zone", "personnel were within the impact zone",
            "operator was near the moving", "person was in the impact zone",
            "worker entered the exclusion zone", "worker entered the impact zone",
        ]) and not no_people and not any_phrase(["did not enter the line of fire", "not in the line of fire", "outside the exclusion zone"])
        explicit_gap = any_phrase([
            "no exclusion zone", "no barricade", "barricade missing", "barricading missing",
            "exclusion zone not maintained", "barricade not maintained", "line of fire was not barricaded",
            "entered the line of fire", "entered the impact zone", "inside the impact zone",
        ]) and not any_phrase(["did not enter the line of fire", "no personnel", "no worker", "outside the exclusion zone"])
        safe = any_phrase([
            "no personnel", "no worker", "outside the exclusion zone", "safe distance",
            "barricade intact", "barricading was intact", "exclusion zone maintained",
            "kept clear", "work stopped", "activity stopped",
        ]) and not (explicit_exposure or explicit_gap)
        active = bool(hazard and (explicit_exposure or explicit_gap) and not safe)
        return {"active": active, "safe": bool(safe and not active), "reason": "Active line-of-fire/impact exposure or barrier failure" if active else "Line-of-fire hazard mentioned but exposure is controlled/not established"}

    if precursor in {"Electrical Contact", "Electrical Isolation Failure"}:
        hazard = any_phrase(["live", "energized", "energised", "electrical contact", "electrical cable", "switchgear", "panel"])
        explicit_gap = any_phrase(["without isolation", "not isolated", "no lockout", "no loto", "live contact", "touched live", "energized while working", "energised while working"])
        safe = any_phrase(["de-energized", "deenergized", "isolated", "lockout", "locked out", "voltage zero", "power isolated"]) and not explicit_gap
        active = bool(hazard and explicit_gap and not safe)
        return {"active": active, "safe": bool(safe and not active), "reason": "Electrical energy with isolation/control failure" if active else "Electrical hazard controlled or exposure not explicit"}

    if precursor in {"Loss of Containment", "Fire and Explosion Potential", "Stored Pressure / Line of Fire", "Process Safety Barrier Failure"}:
        hazard = any_phrase(["leak", "release", "hydrocarbon", "gas", "vapour", "vapor", "pressure", "flammable"])
        explicit_gap = any_phrase([
            "release occurred", "leaking", "leak detected", "pressure remained", "residual pressure",
            "without isolation", "ignition source present", "work continued", "loss of containment",
        ])
        safe = any_phrase(["isolated", "depressurized", "depressurised", "no release", "leak stopped", "leak contained", "gas test clear", "ignition sources removed"]) and not explicit_gap
        active = bool(hazard and explicit_gap and not safe)
        return {"active": active, "safe": bool(safe and not active), "reason": "Process-energy exposure/control failure" if active else "Process hazard controlled or exposure not explicit"}

    return {"active": bool(ctx["active_exposure"] and not ctx["controlled"]), "safe": bool(ctx["controlled"] and not ctx["active_exposure"]), "reason": "Active worker exposure" if ctx["active_exposure"] and not ctx["controlled"] else "Controls/exposure context reduces active SIF concern"}


def _contextual_barriers(precursor, result, ctx_result):
    """Rebuild barrier status from actual control evidence instead of risk label alone."""
    barrier_set = BARRIER_LIBRARY.get(
        precursor,
        {"primary": "General Safety Controls", "supporting": ["Supervision", "Procedure Compliance"]},
    )
    failures = ctx_result.get("control_failures", [])
    positives = ctx_result.get("positive_controls", [])
    active = ctx_result.get("active_pathway", False)

    def status_for(name, primary=False):
        n = name.lower()
        # Barrier-specific failure signals.
        if any(term in n and any(f in f" {' '.join(failures)} " for f in ["missing", "failed", "without", "not ", "no ", "removed", "inadequate"]) for term in ["guard", "fall protection", "exclusion", "barricad", "isolation", "permit", "containment", "scaffold", "access", "movement", "sop", "supervision"]):
            return "Failed"
        if not active and positives:
            return "Intact"
        if failures:
            return "Failed" if primary else "Degraded"
        return "Degraded" if active and primary else "Intact"

    barriers = [{"barrier": barrier_set["primary"], "role": "Primary Barrier", "status": status_for(barrier_set["primary"], True)}]
    for name in barrier_set["supporting"]:
        barriers.append({"barrier": name, "role": "Supporting Barrier", "status": status_for(name, False)})

    failed = sum(b["status"] == "Failed" for b in barriers)
    degraded = sum(b["status"] == "Degraded" for b in barriers)
    overall = "Critical Barrier Failure" if failed else "Barrier Degradation" if degraded else "Barriers Intact"
    return barriers, overall


def _contextual_actions(precursor, active, controlled, base_actions):
    if active:
        return base_actions
    if controlled:
        return [
            "Maintain the identified safety controls and exclusion boundaries.",
            "Verify the control remains effective before and during the activity.",
            "Continue supervisor/HSE verification and record any change in exposure conditions.",
        ]
    return [
        "Verify whether personnel are actually exposed to the identified hazard.",
        "Confirm the relevant barrier/control is effective before work continues.",
        "Escalate to HSE if exposure or control failure is confirmed.",
    ]


def _final_safety_context_analyze(text):
    base = _context_base_analyze_report(text)
    if not base:
        return base

    normalized = base.get("normalized_text", text)
    precursor = base.get("precursor", "")
    ctx = _context_analysis(normalized)
    pctx = _precursor_context(normalized, precursor)
    active = bool(pctx["active"])
    controlled = bool(pctx["safe"] or (ctx["controlled"] and not active))

    # If the pathway override was triggered only because a hazard word appeared
    # in a controlled/negated sentence, cancel the operational override.
    if base.get("pathway_override") and controlled and not active:
        base["pathway_override"] = False
        base["pathway"] = "Context gate: hazard mentioned, but active exposure/control failure was not established"
        base["ml_precursor"] = base.get("ml_precursor", precursor)
        base["pathway_confidence"] = None

    # Risk decision: ML is retained as a signal, but a clear lack of exposure and
    # effective controls prevent a keyword-only HIGH/CRITICAL escalation.
    original_ml = base.get("ml_risk", base.get("risk", "LOW"))
    original_conf = float(base.get("ml_confidence", base.get("confidence", 0.0)))

    if controlled and not active:
        # Controlled hazards should not be labelled HIGH merely because hazard
        # vocabulary is present. Preserve MEDIUM only when the ML signal is strong.
        risk = "MEDIUM" if original_ml == "MEDIUM" else "LOW"
        confidence = min(max(original_conf, 0.55), 0.84)
        priority = "CORRECTIVE" if risk == "MEDIUM" else "ROUTINE"
        base["context_decision"] = "CONTROLLED / NO ACTIVE EXPOSURE"
        base["context_note"] = "Hazard terminology detected, but the narrative contains effective controls or explicit absence of personnel exposure."
    elif not active and not controlled:
        risk = "MEDIUM" if original_ml == "HIGH" else original_ml
        confidence = min(original_conf, 0.80)
        priority = "CORRECTIVE" if risk != "LOW" else "ROUTINE"
        base["context_decision"] = "EXPOSURE NOT ESTABLISHED"
        base["context_note"] = "Hazard is mentioned, but the narrative does not clearly establish active worker exposure or a failed control."
    else:
        # An explicitly active SIF pathway must not remain LOW merely because
        # the historical text classifier was conservative. Active exposure or
        # an active control gap is a safety-critical escalation signal.
        risk = "HIGH" if active else original_ml
        confidence = max(original_conf, 0.75) if active else original_conf
        priority = "IMMEDIATE" if risk == "HIGH" else "CORRECTIVE" if risk == "MEDIUM" else "ROUTINE"
        base["context_decision"] = "ACTIVE EXPOSURE / CONTROL GAP"
        base["context_note"] = pctx["reason"]

    # Explicit actual harm remains an escalation signal.
    severe = base.get("severity_signals", [])
    if severe:
        risk = "HIGH"
        priority = "IMMEDIATE"
        confidence = max(confidence, 0.90)

    base["risk"] = risk
    base["priority"] = priority
    base["confidence"] = min(confidence, 0.95)

    # Recompute SIF score using context, not just keyword count.
    energy = base.get("energy_sources", {})
    latent = base.get("latent_conditions", {})
    recurrence = int(base.get("recurrence_count", 0) or 0)
    score = 0
    score += min(20, 5 * len(energy))
    score += 35 if active else 0
    score += min(15, 5 * len(latent))
    score += min(5, recurrence / max(len(df), 1) * 50)
    if severe:
        score += 30
    elif base.get("consequence") in {"Fatality", "Serious Injury"} and active:
        score += 20
    if controlled and not active:
        score = min(score, 25)
    elif not active:
        score = min(score, 40)
    # Active exposure plus a control gap is safety-critical even when the
    # statistical model is conservative. Keep the numeric score aligned with
    # the operational risk label so the UI cannot show HIGH + MEDIUM SIF band.
    if active:
        score = max(score, 65)
    elif not active and not controlled:
        score = max(score, 30) if original_ml == "MEDIUM" else score
    score = int(round(min(100, score)))
    band = "CRITICAL" if score >= 80 else "HIGH" if score >= 60 else "MEDIUM" if score >= 35 else "LOW"
    if severe:
        band = "HIGH"
        score = max(score, 70)
    base["sif_score"] = score
    base["sif_band"] = band

    # Context-aware exposure object.
    base["exposure"] = {
        "worker_exposure": active,
        "direct_exposure": active,
        "people_terms": [x for x in _PEOPLE_WORDS if x in normalized.lower()],
        "status": "Active exposure" if active else "No active exposure established",
        "positive_controls": ctx["positive_controls"],
        "control_failures": ctx["control_failures"],
    }

    # Context-aware barriers and actions.
    barrier_ctx = {
        "active_pathway": active,
        "positive_controls": ctx["positive_controls"],
        "control_failures": ctx["control_failures"],
    }
    barriers, barrier_status = _contextual_barriers(precursor, base, barrier_ctx)
    base["barriers"] = barriers
    base["barrier_status"] = barrier_status
    base["actions"] = _contextual_actions(precursor, active, controlled, base.get("actions", []))

    # Rebuild explainability so the UI tells the HSE reviewer what the context gate did.
    context_evidence = []
    for x in ctx["positive_controls"]:
        context_evidence.append(f"Control confirmed: {x}")
    for x in ctx["control_failures"]:
        context_evidence.append(f"Control gap: {x}")
    if ctx["no_exposure_sentences"]:
        context_evidence.append("No personnel exposure explicitly stated")
    base["evidence"] = list(dict.fromkeys(base.get("evidence", []) + context_evidence))
    base["context_evidence"] = context_evidence

    if controlled and not active:
        base["pathway"] = "Hazard identified → control/exclusion verified → no active worker exposure → monitored condition"

    # Distinguish the historical/ML hazard category from an operational ACTIVE
    # SIF precursor. Hazard vocabulary alone is not an active precursor.
    base["hazard_category"] = precursor or "Unclassified"
    base["active_precursor"] = precursor if active or severe else "None — controlled / no active exposure"
    base["assessment_confidence"] = min(float(base.get("confidence", 0.0)), 0.95)

    # Keep consequence prediction informational; do not convert a word mention
    # into an active consequence when exposure is explicitly absent.
    if controlled and not active and not severe:
        base["consequence_confidence"] = min(float(base.get("consequence_confidence", 0.35)), 0.55)

    return base


# Preserve the previous V2 function as an internal implementation and expose
# the context-gated version to every page that calls analyze_report().
_context_base_analyze_report = analyze_report
analyze_report = _final_safety_context_analyze

