similarity_vectorizer = TfidfVectorizer(
    stop_words="english",
    ngram_range=(1, 2),
)

similarity_matrix = similarity_vectorizer.fit_transform(
    df["Report"]
)


def find_similar_reports(text, top_n=5):
    query_vector = similarity_vectorizer.transform([text])

    scores = cosine_similarity(
        query_vector,
        similarity_matrix,
    )[0]

    result = df.copy()
    result["Similarity"] = scores

    return (
        result
        .sort_values("Similarity", ascending=False)
        .head(top_n)
    )


